From e913aada06830338633fb8524733b0ad3d38a7c1 Mon Sep 17 00:00:00 2001
From: Pawel Laszczak <pawell@cadence.com>
Date: Wed, 23 Jun 2021 09:27:28 +0200
Subject: [PATCH] usb: cdnsp: Fixed issue with ZLP

The condition "if (need_zero_pkt && zero_len_trb)" was always false
and it caused that TRB for ZLP was not prepared.

Fix causes that after preparing last TRB in TD, the driver prepares
additional TD with ZLP when a ZLP is required.

Cc: <stable@vger.kernel.org>
Fixes: 3d82904559f4 ("usb: cdnsp: cdns3 Add main part of Cadence USBSSP DRD Driver")
Signed-off-by: Pawel Laszczak <pawell@cadence.com>
Link: https://lore.kernel.org/r/20210623072728.41275-1-pawell@gli-login.cadence.com
Signed-off-by: Peter Chen <peter.chen@kernel.org>

diff --git a/drivers/usb/cdns3/cdnsp-ring.c b/drivers/usb/cdns3/cdnsp-ring.c
index 68972746e363..1b1438457fb0 100644
--- a/drivers/usb/cdns3/cdnsp-ring.c
+++ b/drivers/usb/cdns3/cdnsp-ring.c
@@ -1932,15 +1932,13 @@ int cdnsp_queue_bulk_tx(struct cdnsp_device *pdev, struct cdnsp_request *preq)
 		}

 		if (enqd_len + trb_buff_len >= full_len) {
-			if (need_zero_pkt && zero_len_trb) {
-				zero_len_trb = true;
-			} else {
-				field &= ~TRB_CHAIN;
-				field |= TRB_IOC;
-				more_trbs_coming = false;
-				need_zero_pkt = false;
-				preq->td.last_trb = ring->enqueue;
-			}
+			if (need_zero_pkt)
+				zero_len_trb = !zero_len_trb;
+
+			field &= ~TRB_CHAIN;
+			field |= TRB_IOC;
+			more_trbs_coming = false;
+			preq->td.last_trb = ring->enqueue;
 		}

 		/* Only set interrupt on short packet for OUT endpoints. */
@@ -1955,7 +1953,7 @@ int cdnsp_queue_bulk_tx(struct cdnsp_device *pdev, struct cdnsp_request *preq)
 		length_field = TRB_LEN(trb_buff_len) | TRB_TD_SIZE(remainder) |
 			TRB_INTR_TARGET(0);

-		cdnsp_queue_trb(pdev, ring, more_trbs_coming | need_zero_pkt,
+		cdnsp_queue_trb(pdev, ring, more_trbs_coming | zero_len_trb,
 				lower_32_bits(send_addr),
 				upper_32_bits(send_addr),
 				length_field,
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the condition `if (need_zero_pkt && zero_len_trb)` always evaluating to false, which prevented the preparation of a TRB for a Zero-Length Packet (ZLP) when it was required. This oversight meant that the driver did not handle the case where a ZLP needed to be sent after the last TRB, leading to potential issues in data transmission.

        Commit message:
        usb: cdnsp: Fixed issue with ZLP

The condition "if (need_zero_pkt && zero_len_trb)" was always false
and it caused that TRB for ZLP was not prepared.

Fix causes that after preparing last TRB in TD, the driver prepares
additional TD with ZLP when a ZLP is required.

Cc: <stable@vger.kernel.org>
Fixes: 3d82904559f4 ("usb: cdnsp: cdns3 Add main part of Cadence USBSSP DRD Driver")
Signed-off-by: Pawel Laszczak <pawell@cadence.com>
Link: https://lore.kernel.org/r/20210623072728.41275-1-pawell@gli-login.cadence.com
Signed-off-by: Peter Chen <peter.chen@kernel.org>  

        Patch:

 int cdnsp_queue_bulk_tx(struct cdnsp_device *pdev, struct cdnsp_request *preq)
 {
 	unsigned int enqd_len, block_len, trb_buff_len, full_len;
 	unsigned int start_cycle, num_sgs = 0;
 	struct cdnsp_generic_trb *start_trb;
 	u32 field, length_field, remainder;
 	struct scatterlist *sg = NULL;
 	bool more_trbs_coming = true;
 	bool need_zero_pkt = false;
 	bool zero_len_trb = false;
 	struct cdnsp_ring *ring;
 	bool first_trb = true;
 	unsigned int num_trbs;
 	struct cdnsp_ep *pep;
 	u64 addr, send_addr;
 	int sent_len, ret;

 	ring = cdnsp_request_to_transfer_ring(pdev, preq);
 	if (!ring)
 		return -EINVAL;

 	full_len = preq->request.length;

 	if (preq->request.num_sgs) {
 		num_sgs = preq->request.num_sgs;
 		sg = preq->request.sg;
 		addr = (u64)sg_dma_address(sg);
 		block_len = sg_dma_len(sg);
 		num_trbs = count_sg_trbs_needed(preq);
 	} else {
 		num_trbs = count_trbs_needed(preq);
 		addr = (u64)preq->request.dma;
 		block_len = full_len;
 	}

 	pep = preq->pep;

 	/* Deal with request.zero - need one more td/trb. */
 	if (preq->request.zero && preq->request.length &&
 	    IS_ALIGNED(full_len, usb_endpoint_maxp(pep->endpoint.desc))) {
 		need_zero_pkt = true;
 		num_trbs++;
 	}

 	ret = cdnsp_prepare_transfer(pdev, preq, num_trbs);
 	if (ret)
 		return ret;

 	/*
 	 * Don't give the first TRB to the hardware (by toggling the cycle bit)
 	 * until we've finished creating all the other TRBs. The ring's cycle
 	 * state may change as we enqueue the other TRBs, so save it too.
 	 */
 	start_trb = &ring->enqueue->generic;
 	start_cycle = ring->cycle_state;
 	send_addr = addr;

 	/* Queue the TRBs, even if they are zero-length */
 	for (enqd_len = 0; zero_len_trb || first_trb || enqd_len < full_len;
 	     enqd_len += trb_buff_len) {
 		field = TRB_TYPE(TRB_NORMAL);

 		/* TRB buffer should not cross 64KB boundaries */
 		trb_buff_len = TRB_BUFF_LEN_UP_TO_BOUNDARY(addr);
 		trb_buff_len = min(trb_buff_len, block_len);
 		if (enqd_len + trb_buff_len > full_len)
 			trb_buff_len = full_len - enqd_len;

 		/* Don't change the cycle bit of the first TRB until later */
 		if (first_trb) {
 			first_trb = false;
 			if (start_cycle == 0)
 				field |= TRB_CYCLE;
 		} else {
 			field |= ring->cycle_state;
 		}

 		/*
 		 * Chain all the TRBs together; clear the chain bit in the last
 		 * TRB to indicate it's the last TRB in the chain.
 		 */
 		if (enqd_len + trb_buff_len < full_len || need_zero_pkt) {
 			field |= TRB_CHAIN;
 			if (cdnsp_trb_is_link(ring->enqueue + 1)) {
 				if (cdnsp_align_td(pdev, preq, enqd_len,
 						   &trb_buff_len,
 						   ring->enq_seg)) {
 					send_addr = ring->enq_seg->bounce_dma;
 					/* Assuming TD won't span 2 segs */
 					preq->td.bounce_seg = ring->enq_seg;
 				}
 			}
 		}

 		if (enqd_len + trb_buff_len >= full_len) {
-			if (need_zero_pkt && zero_len_trb) {
-				zero_len_trb = true;
-			} else {
-				field &= ~TRB_CHAIN;
-				field |= TRB_IOC;
-				more_trbs_coming = false;
-				need_zero_pkt = false;
-				preq->td.last_trb = ring->enqueue;
-			}
+			if (need_zero_pkt)
+				zero_len_trb = !zero_len_trb;
+
+			field &= ~TRB_CHAIN;
+			field |= TRB_IOC;
+			more_trbs_coming = false;
+			preq->td.last_trb = ring->enqueue;
 		}

 		/* Only set interrupt on short packet for OUT endpoints. */
 		if (!preq->direction)
 			field |= TRB_ISP;

 		/* Set the TRB length, TD size, and interrupter fields. */
 		remainder = cdnsp_td_remainder(pdev, enqd_len, trb_buff_len,
 					       full_len, preq,
 					       more_trbs_coming);

 		length_field = TRB_LEN(trb_buff_len) | TRB_TD_SIZE(remainder) |
 			TRB_INTR_TARGET(0);

-		cdnsp_queue_trb(pdev, ring, more_trbs_coming | need_zero_pkt,
+		cdnsp_queue_trb(pdev, ring, more_trbs_coming | zero_len_trb,
 				lower_32_bits(send_addr),
 				upper_32_bits(send_addr),
 				length_field,
 				field);

 		addr += trb_buff_len;
 		sent_len = trb_buff_len;
 		while (sg && sent_len >= block_len) {
 			/* New sg entry */
 			--num_sgs;
 			sent_len -= block_len;
 			if (num_sgs != 0) {
 				sg = sg_next(sg);
 				block_len = sg_dma_len(sg);
 				addr = (u64)sg_dma_address(sg);
 				addr += sent_len;
 			}
 		}
 		block_len -= sent_len;
 		send_addr = addr;
 	}

 	cdnsp_check_trb_math(preq, enqd_len);
 	ret = cdnsp_giveback_first_trb(pdev, pep, preq->request.stream_id,
 				       start_cycle, start_trb);

 	if (ret)
 		preq->td.drbl = 1;

 	return 0;
 }



